def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    ones=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # Connect any pair of 1 markers on a 45-degree diagonal, preserving other colors.
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if abs(r2-r1)==abs(c2-c1):
                sr=1 if r2>r1 else -1
                sc=1 if c2>c1 else -1
                for k in range(abs(r2-r1)+1):
                    r,c=r1+k*sr,c1+k*sc
                    if out[r][c]==4: out[r][c]=1
    # A 6 marker lying on a completed 1 diagonal extends 6 along its own diagonal.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6 and out[r][c]==6:
                # only expand if cell is strictly on a 1-to-1 diagonal
                if any(min(a[0],b[0])<=r<=max(a[0],b[0]) and
